const upsertBankPosting = `-- name: UpsertBankPosting :one
INSERT INTO bank_transaction_postings (organization_id, engagement_id, taxpayer_id, bank_transaction_id,
                                       account_code, account_name, status, confidence, source, reason, suggestion_id)
VALUES ($1, $2, $3, $4, $5, $6,
        'suggested', $7, $8, $9, $10)
ON CONFLICT (engagement_id, bank_transaction_id) DO UPDATE
SET account_code = EXCLUDED.account_code, account_name = EXCLUDED.account_name, confidence = EXCLUDED.confidence,
    source = EXCLUDED.source, reason = EXCLUDED.reason, suggestion_id = EXCLUDED.suggestion_id
WHERE bank_transaction_postings.status = 'suggested'
RETURNING id, organization_id, engagement_id, taxpayer_id, bank_transaction_id, account_code, account_name, status, confidence, source, reason, suggestion_id, journal_draft_uuid, approved_by, approved_at, created_at, updated_at, commission_amount, commission_account_code
`

type UpsertBankPostingParams struct {
	OrganizationID    int64          `json:"organization_id"`
	EngagementID      int64          `json:"engagement_id"`
	TaxpayerID        int64          `json:"taxpayer_id"`
	BankTransactionID int64          `json:"bank_transaction_id"`
	AccountCode       string         `json:"account_code"`
	AccountName       string         `json:"account_name"`
	Confidence        pgtype.Numeric `json:"confidence"`
	Source            string         `json:"source"`
	Reason            string         `json:"reason"`
	SuggestionID      pgtype.Int8    `json:"suggestion_id"`
}

// Öneri yazılır; onaylanmış bir hareketin önerisi değişmez.
func (q *Queries) UpsertBankPosting(ctx context.Context, arg UpsertBankPostingParams) (BankTransactionPosting, error) {
	row := q.db.QueryRow(ctx, upsertBankPosting,
		arg.OrganizationID,
		arg.EngagementID,
		arg.TaxpayerID,
		arg.BankTransactionID,
		arg.AccountCode,
		arg.AccountName,
		arg.Confidence,
		arg.Source,
		arg.Reason,
		arg.SuggestionID,
	)
	var i BankTransactionPosting
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.EngagementID,
		&i.TaxpayerID,
		&i.BankTransactionID,
		&i.AccountCode,
		&i.AccountName,
		&i.Status,
		&i.Confidence,
		&i.Source,
		&i.Reason,
		&i.SuggestionID,
		&i.JournalDraftUuid,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CommissionAmount,
		&i.CommissionAccountCode,
	)
	return i, err
}
